<template>
  <main class="paper-shell"><div class="paper-container tool-container"><header class="paper-workspace-header"><div><div class="paper-page-eyebrow">Knowledge Base / Authors</div><h1 class="paper-page-title">Scholar directory</h1><p class="paper-page-description">Search author records, affiliations, identifiers, publication counts, citations, and h-index.</p></div></header><LiteratureKnowledgeNav />
    <form class="paper-panel author-filters" @submit.prevent="load"><label>Name<input v-model="query" placeholder="Author name" /></label><label>Affiliation<input v-model="affiliation" placeholder="Institution" /></label><label>ORCID<input v-model="orcid" placeholder="0000-0000-0000-0000" /></label><button class="paper-button primary">Search</button></form><p v-if="error" class="notice">{{ error }}</p>
    <section class="paper-panel authors-table"><div class="section-heading"><strong>Authors</strong><span>{{ total }} records</span></div><table v-if="authors.length"><thead><tr><th>Name</th><th>Affiliation</th><th>Papers</th><th>Citations</th><th>h-index</th><th>ORCID</th></tr></thead><tbody><tr v-for="author in authors" :key="author.id" @click="router.push(`/literature/authors/${author.id}`)"><td><strong>{{ author.full_name }}</strong></td><td>{{ author.current_affiliation||author.affiliation||'—' }}</td><td>{{ author.paper_count||author.total_papers||0 }}</td><td>{{ author.total_citations||0 }}</td><td>{{ author.h_index||'—' }}</td><td>{{ author.orcid||'—' }}</td></tr></tbody></table><div v-else class="empty">{{ pending?'Loading authors…':'No authors found.' }}</div></section>
  </div></main>
</template>
<script setup>
import '~/assets/paper-platform.css';import LiteratureKnowledgeNav from '~/components/LiteratureKnowledgeNav.vue'
const config=useRuntimeConfig(),router=useRouter(),route=useRoute(),query=ref(String(route.query.q||'')),affiliation=ref(String(route.query.affiliation||'')),orcid=ref(''),authors=ref([]),total=ref(0),pending=ref(false),error=ref('');useHead({title:'Literature Authors - OpenIsle'})
const load=async()=>{pending.value=true;error.value='';try{const p=new URLSearchParams({limit:'100',offset:'0'});if(query.value.trim())p.set('q',query.value.trim());if(affiliation.value.trim())p.set('affiliation',affiliation.value.trim());if(orcid.value.trim())p.set('orcid',orcid.value.trim());const data=await $fetch(`${config.public.apiBaseUrl}/api/literature/explore/authors/list?${p}`);authors.value=data.authors||[];total.value=data.total??authors.value.length}catch(cause){error.value=cause?.data?.message||cause?.message||'Unable to load authors.'}finally{pending.value=false}};onMounted(load)
</script>
<style scoped>
.tool-container{max-width:1180px}.author-filters{display:grid;grid-template-columns:1fr 1fr 1fr auto;gap:10px;align-items:end;padding:15px;margin-bottom:16px}.author-filters label{display:grid;gap:5px;color:var(--paper-muted);font-size:11px;font-weight:750}.author-filters input{min-height:39px;border:1px solid var(--paper-line);padding:8px 10px}.authors-table{overflow:hidden}.section-heading{display:flex;justify-content:space-between;padding:14px 18px;border-bottom:1px solid var(--paper-line)}.section-heading span{color:var(--paper-muted);font-size:11px}.authors-table table{width:100%;border-collapse:collapse}.authors-table th,.authors-table td{padding:11px 14px;border-bottom:1px solid var(--paper-line);text-align:left;font-size:12px}.authors-table th{color:var(--paper-muted);font-size:10px;text-transform:uppercase}.authors-table tbody tr{cursor:pointer}.authors-table tbody tr:hover{background:#f5f9fa}.empty{padding:50px;text-align:center;color:var(--paper-muted)}.notice{padding:10px 14px;background:#fff4f2;color:#8b3028}@media(max-width:800px){.author-filters{grid-template-columns:1fr 1fr}}
</style>
